/**
 * API object types. They are derived from the OpenAPI schema (schema.d.ts, generated by
 * "npm run gen:types"), not hand-written, so the two apps cannot drift from the backend (CR-005).
 * The option lists below are typed against the generated enums: a value the API does not accept
 * fails the build.
 */
import type { components } from "./schema";

type Schemas = components["schemas"];
/** A response row: every field is present in a response, so the optional markers are removed. */
type Row<K extends keyof Schemas> = Required<Schemas[K]>;

export type Station = Row<"Station">;
export type StationOperator = Row<"StationOperator">;
export type Sensor = Row<"Sensor">;
export type Calibration = Row<"CalibrationList">;
export type MetricType = Row<"MetricType">;
export type Observation = Row<"Observation">;
export type UploadBatch = Row<"UploadBatch">;
export type Baseline = Row<"Baseline">;
export type CarbonEmissionLog = Row<"CarbonEmissionLog">;
export type ExtremeWeatherEvent = Row<"ExtremeWeatherEvent">;
export type RenewableEnergyFeed = Row<"RenewableEnergyFeed">;
export type CommunityRiskRating = Row<"CommunityRiskRating">;
export type InfrastructureLog = Row<"InfrastructureLog">;
export type User = Row<"User">;
export type Role = Row<"Role">;
export type AuditTrail = Row<"AuditTrail">;
export type GeneratedReport = Row<"GeneratedReport">;
export type Farmer = Row<"Farmer">;
export type SmsMessage = Row<"SmsMessage">;
export type IncomingSms = Row<"IncomingSms">;

export type Province = Schemas["ProvinceEnum"];
export type StationType = Schemas["StationTypeEnum"];
export type StationStatus = Schemas["StationStatusEnum"];
export type SensorStatus = Schemas["SensorStatusEnum"];
export type CalibrationStatus = Schemas["CalibrationStatusEnum"];
export type CalibrationResult = Schemas["ResultEnum"];
export type QualityFlag = Schemas["QualityFlagEnum"];
export type ObservationSource = Schemas["SourceEnum"];
export type Severity = Schemas["SeverityEnum"];
export type BatchStatus = Schemas["UploadBatchStatusEnum"];
export type Language = Schemas["LanguageEnum"];
export type SmsKind = Schemas["KindEnum"];
export type SmsStatus = Schemas["SmsMessageStatusEnum"];
export type IncomingKind = Schemas["KeywordEnum"];

/** The one list shape of the API: every list endpoint is paginated like this. */
export interface Page<T> {
  count: number;
  next: string | null;
  previous: string | null;
  results: T[];
}

