export const STATION_STATUSES: StationStatus[] = ["Active", "Inactive", "Decommissioned"];
export const SENSOR_STATUSES: SensorStatus[] = ["Active", "Faulty", "Out for calibration", "Retired"];
export const CALIBRATION_STATUSES: CalibrationStatus[] = ["Current", "Due", "Overdue", "Unknown"];
export const CALIBRATION_RESULTS: CalibrationResult[] = ["Pass", "Adjusted", "Fail"];
export const QUALITY_FLAGS: QualityFlag[] = ["Valid", "Suspect", "Estimated", "Rejected"];
export const SOURCES: ObservationSource[] = ["Manual", "Bulk upload", "Telemetry", "Model"];
