export const SOURCE_LABEL: Record<ObservationSource, string> = {
  Manual: "Manual", "Bulk upload": "Bulk upload", Telemetry: "Telemetry", Model: "Weather model",
};
export const SEVERITIES: Severity[] = ["Low", "Moderate", "High", "Extreme"];
